class Commit:
    def __init__(self, id_commit, mensagem, arquivos):
        self.id_commit = id_commit
        self.mensagem = mensagem
        self.arquivos = arquivos.copy()

    def __str__(self):
        return f"[{self.id_commit}] {self.mensagem} ({len(self.arquivos)} arquivo(s))"

class Repositorio:
    def __init__(self):
        self.staging = []
        self.commits = []
    def add(self, arquivo):
        self.staging.append(arquivo)
        return len(self.staging)

repo = Repositorio()
repo.add("main.py")
print(f"Arquivos em staging: {repo.staging}")
